    { const char * tb_v898 = "TB_API double atan2(double y, double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v898; }
    { const char * tb_v899 = "    const double pi = 3.14159265358979323846;\n"; *(const char * *)tb_grow(v_lines) = tb_v899; }
    { const char * tb_v900 = "    if (x > 0) return atan(y / x);\n"; *(const char * *)tb_grow(v_lines) = tb_v900; }
    { const char * tb_v901 = "    if (x < 0) return y >= 0 ? atan(y / x) + pi : atan(y / x) - pi;\n"; *(const char * *)tb_grow(v_lines) = tb_v901; }
    { const char * tb_v902 = "    return y > 0 ? pi / 2 : y < 0 ? -pi / 2 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v902; }
    { const char * tb_v903 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v903; }
    { const char * tb_v904 = "TB_API double exp(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v904; }
    { const char * tb_v905 = "    if (x > 709) return 1e308;\n"; *(const char * *)tb_grow(v_lines) = tb_v905; }
    { const char * tb_v906 = "    if (x < -745) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v906; }
    { const char * tb_v907 = "    long long k = (long long)floor(x / 0.6931471805599453 + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v907; }
    { const char * tb_v908 = "    double r = x - (double)k * 0.6931471805599453, t = 1, s = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v908; }
    { const char * tb_v909 = "    for (int i = 1; i < 18; i++) { t *= r / i; s += t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v909; }
