    { const char * tb_v911 = "    v.u += (unsigned long long)k << 52;\n"; *(const char * *)tb_grow(v_lines) = tb_v911; }
    { const char * tb_v912 = "    return v.d;\n"; *(const char * *)tb_grow(v_lines) = tb_v912; }
    { const char * tb_v913 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v913; }
    { const char * tb_v914 = "TB_API double log(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v914; }
    { const char * tb_v915 = "    if (x <= 0) return -1e308;\n"; *(const char * *)tb_grow(v_lines) = tb_v915; }
    { const char * tb_v916 = "    union { double d; unsigned long long u; } v; v.d = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v916; }
    { const char * tb_v917 = "    long long e = (long long)((v.u >> 52) & 0x7FF) - 1023;\n"; *(const char * *)tb_grow(v_lines) = tb_v917; }
    { const char * tb_v918 = "    v.u = (v.u & 0x000FFFFFFFFFFFFFull) | 0x3FF0000000000000ull;   // 1 <= m < 2\n"; *(const char * *)tb_grow(v_lines) = tb_v918; }
    { const char * tb_v919 = "    double m = v.d;\n"; *(const char * *)tb_grow(v_lines) = tb_v919; }
    { const char * tb_v920 = "    if (m > 1.4142135623730951) { m /= 2; e++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v920; }
    { const char * tb_v921 = "    double y = (m - 1) / (m + 1), y2 = y * y, t = y, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v921; }
    { const char * tb_v922 = "    for (int k = 0; k < 20; k++) { r += t / (2 * k + 1); t *= y2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v922; }
