    { const char * tb_v924 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v924; }
    { const char * tb_v925 = "TB_API double pow(double a, double b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v925; }
    { const char * tb_v926 = "    if (b == 0) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v926; }
    { const char * tb_v927 = "    if (a == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v927; }
    { const char * tb_v928 = "    if (b == (double)(long long)b && b > -64 && b < 64) {\n"; *(const char * *)tb_grow(v_lines) = tb_v928; }
    { const char * tb_v929 = "        double r = 1, m = a; long long n = (long long)(b < 0 ? -b : b);\n"; *(const char * *)tb_grow(v_lines) = tb_v929; }
    { const char * tb_v930 = "        while (n) { if (n & 1) r *= m; m *= m; n >>= 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v930; }
    { const char * tb_v931 = "        return b < 0 ? 1 / r : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v931; }
    { const char * tb_v932 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v932; }
    { const char * tb_v933 = "    if (a < 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v933; }
    { const char * tb_v934 = "    return exp(b * log(a));\n"; *(const char * *)tb_grow(v_lines) = tb_v934; }
    { const char * tb_v935 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v935; }
    { const char * tb_v936 = "TB_API float powf(float a, float b) { return (float)pow(a, b); }\n"; *(const char * *)tb_grow(v_lines) = tb_v936; }
    { const char * tb_v937 = "TB_API void *bsearch(const void *key, const void *base, size_t n, size_t size, int (*cmp)(const void *, const void *)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v937; }
    { const char * tb_v938 = "    size_t lo = 0, hi = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v938; }
    { const char * tb_v939 = "    while (lo < hi) {\n"; *(const char * *)tb_grow(v_lines) = tb_v939; }
