    { const char * tb_v945 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v945; }
    { const char * tb_v946 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v946; }
    { const char * tb_v947 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v947; }
