    { const char * tb_v950 = "// ---------- ядро: прерывания, таймер, клавиатура, задачи, страницы памяти ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v950; }
    { const char * tb_v951 = "// on all cores здесь выполняется на одном ядре по очереди (как и было),\n"; *(const char * *)tb_grow(v_lines) = tb_v951; }
    { const char * tb_v952 = "// а background — настоящая задача: таймер переключает задачи каждые 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v952; }
