    { const char * tb_v1240 = "// ---- модули (файлы, которые загрузчик положил рядом с ядром: qemu -initrd \"a.oapp,b.oapp\") ----\n"; *(const char * *)tb_grow(v_lines) = tb_v1240; }
    { const char * tb_v1241 = "// у Multiboot: флаг 3 — есть модули; mbi[5] — сколько, mbi[6] — где список (по 16 байт: начало, конец, имя, 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v1241; }
