    { const char * tb_v1250 = "    long long n; uint32_t *m = tb_mods(&n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1250; }
    { const char * tb_v1251 = "    uint64_t top = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1251; }
