    { const char * tb_v1263 = "// таблица имён ядра (её заполняет компоновщик elf_link.py): по алфавиту, 16 байт на имя —\n"; *(const char * *)tb_grow(v_lines) = tb_v1263; }
    { const char * tb_v1264 = "// адрес, где имя (от начала таблицы), длина имени. Программы Омниума находят по ней функции ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v1264; }
    { const char * tb_v1265 = "TB_API volatile uint64_t tb_ksym_tab __attribute__((used)) = 1, tb_ksym_n __attribute__((used)) = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1265; }
    { const char * tb_v1266 = "TB_API long long tb_kernel_symbol(const char *nm) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1266; }
    { const char * tb_v1267 = "    uint64_t t = tb_ksym_tab;\n"; *(const char * *)tb_grow(v_lines) = tb_v1267; }
    { const char * tb_v1268 = "    long long lo = 0, hi = (long long)tb_ksym_n - 1, len = (long long)strlen(nm);\n"; *(const char * *)tb_grow(v_lines) = tb_v1268; }
    { const char * tb_v1269 = "    if (t <= 1) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1269; }
    { const char * tb_v1270 = "    while (lo <= hi) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1270; }
    { const char * tb_v1271 = "        long long mid = (lo + hi) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v1271; }
    { const char * tb_v1272 = "        const uint64_t *e = (const uint64_t *)(uintptr_t)(t + 16 * mid);\n"; *(const char * *)tb_grow(v_lines) = tb_v1272; }
    { const char * tb_v1273 = "        uint32_t off = (uint32_t)e[1], n = (uint32_t)(e[1] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v1273; }
    { const char * tb_v1274 = "        int r = memcmp((const char *)(uintptr_t)(t + off), nm, (size_t)(n < len ? n : len));\n"; *(const char * *)tb_grow(v_lines) = tb_v1274; }
    { const char * tb_v1275 = "        if (r == 0) r = n < len ? -1 : n > len ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1275; }
