    { const char * tb_v1920 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v1920; }
    { const char * tb_v1921 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v1921; }
    { const char * tb_v1922 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1922; }
