    { const char * tb_v1964 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1964; }
    { const char * tb_v1965 = "// свой маленький стек для сообщения: у главного потока — постоянный, у остальных — из malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1965; }
    { const char * tb_v1966 = "TB_API void tb_guard_thread(char *here, long long lim) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1966; }
