    { const char * tb_v2216 = "// адрес → страница: таблица в два шага (биты 47..32, потом 31..16)\n"; *(const char * *)tb_grow(v_lines) = tb_v2216; }
    { const char * tb_v2217 = "TB_API tb_gpage **tb_gdir[1 << 16];\n"; *(const char * *)tb_grow(v_lines) = tb_v2217; }
    { const char * tb_v2218 = "TB_API uintptr_t tb_glo = ~(uintptr_t)0, tb_ghi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2218; }
    { const char * tb_v2219 = "TB_API long long tb_gsince = 0, tb_glive = 0, tb_gnext = 8LL << 20, tb_gstress = 0, tb_gcount = 0, tb_gruns = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2219; }
    { const char * tb_v2220 = "TB_API int tb_gready = 0, tb_goff = 0, tb_gstats = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2220; }
    { const char * tb_v2221 = "TB_API char *tb_gtop = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2221; }
    { const char * tb_v2222 = "TB_API pthread_mutex_t tb_glock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2222; }
    { const char * tb_v2223 = "TB_API tb_grange *tb_groots = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2223; }
    { const char * tb_v2224 = "TB_API long long tb_gnroots = 0, tb_gcaproots = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2224; }
    { const char * tb_v2225 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2225; }
    { const char * tb_v2226 = "TB_API void tb_gsetup(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2226; }
    { const char * tb_v2227 = "    int c = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2227; }
