    { const char * tb_v2231 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2231; }
    { const char * tb_v2232 = "    tb_gready = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2232; }
