    { const char * tb_v2234 = "TB_INL tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2234; }
    { const char * tb_v2235 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2235; }
    { const char * tb_v2236 = "    tb_gpage **l2 = tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v2236; }
