    { const char * tb_v2284 = "    return (char *)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v2284; }
    { const char * tb_v2285 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2285; }
    { const char * tb_v2286 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2286; }
    { const char * tb_v2287 = "// страницы по 64 КБ берём у системы пачкой по 4 МБ; пустые страницы возвращаются в запас\n"; *(const char * *)tb_grow(v_lines) = tb_v2287; }
