    { const char * tb_v2709 = "    tb_list *l = tb_mem(sizeof(tb_list));\n"; *(const char * *)tb_grow(v_lines) = tb_v2709; }
    { const char * tb_v2710 = "    l->len = 0; l->cap = 64; l->size = 0; l->data = tb_mem_np(8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2710; }
