    { const char * tb_v3719 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3719; }
    { const char * tb_v3720 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3720; }
    { const char * tb_v3721 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3721; }
    { const char * tb_v3722 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v3722; }
