    { const char * tb_v3862 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3862; }
    { const char * tb_v3863 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3863; }
    { const char * tb_v3864 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3864; }
