    { const char * tb_v3875 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3875; }
    { const char * tb_v3876 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3876; }
    { const char * tb_v3877 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v3877; }
    { const char * tb_v3878 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3878; }
