    { const char * tb_v3886 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3886; }
    { const char * tb_v3887 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3887; }
    { const char * tb_v3888 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v3888; }
    { const char * tb_v3889 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3889; }
