    { const char * tb_v4051 = "// ---------- память руками: new_mem, free_mem, grow_mem, copy_mem, fill_mem (только в danger) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4051; }
    { const char * tb_v4052 = "// Перед каждым блоком 16 байт: размер и метка «живой» / «освобождён» — так free_mem ловит чужой\n"; *(const char * *)tb_grow(v_lines) = tb_v4052; }
    { const char * tb_v4053 = "// адрес и второе освобождение. TB_MEM_CHECK=1 (не в ядре): за блоком 16 байт-сторожей, освобождённые\n"; *(const char * *)tb_grow(v_lines) = tb_v4053; }
    { const char * tb_v4054 = "// блоки не отдаются обратно (их чтение и запись ловятся), read/write/copy_mem/fill_mem проверяют\n"; *(const char * *)tb_grow(v_lines) = tb_v4054; }
    { const char * tb_v4055 = "// адрес, а в конце программы печатается, что не освобождено\n"; *(const char * *)tb_grow(v_lines) = tb_v4055; }
    { const char * tb_v4056 = "#define TB_MEM_LIVE 0x4D454D4C49564521ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v4056; }
    { const char * tb_v4057 = "#define TB_MEM_DEAD 0x4D454D4445414421ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v4057; }
    { const char * tb_v4058 = "#define TB_MEM_GUARD 16\n"; *(const char * *)tb_grow(v_lines) = tb_v4058; }
    { const char * tb_v4059 = "typedef struct { uint64_t size, magic; } tb_memh;\n"; *(const char * *)tb_grow(v_lines) = tb_v4059; }
    { const char * tb_v4060 = "typedef struct { uintptr_t a; uint64_t n; int live, line, fline; } tb_memb;\n"; *(const char * *)tb_grow(v_lines) = tb_v4060; }
    { const char * tb_v4061 = "TB_API int tb_mem_check = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4061; }
