    { const char * tb_v4066 = "TB_INL int tb_memchk(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4066; }
    { const char * tb_v4067 = "    if (TB_RARE(tb_mem_check < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4067; }
    { const char * tb_v4068 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4068; }
    { const char * tb_v4069 = "        tb_mem_check = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4069; }
    { const char * tb_v4070 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4070; }
    { const char * tb_v4071 = "        const char *e = getenv(\"TB_MEM_CHECK\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4071; }
    { const char * tb_v4072 = "        tb_mem_check = e && e[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v4072; }
    { const char * tb_v4073 = "        if (tb_mem_check) atexit(tb_mem_report);\n"; *(const char * *)tb_grow(v_lines) = tb_v4073; }
    { const char * tb_v4074 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4074; }
    { const char * tb_v4075 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4075; }
    { const char * tb_v4076 = "    return tb_mem_check;\n"; *(const char * *)tb_grow(v_lines) = tb_v4076; }
    { const char * tb_v4077 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4077; }
    { const char * tb_v4078 = "static void tb_mem_lock(void) { while (__sync_lock_test_and_set(&tb_mem_spin, 1)) { } }\n"; *(const char * *)tb_grow(v_lines) = tb_v4078; }
    { const char * tb_v4079 = "static void tb_mem_unlock(void) { __sync_lock_release(&tb_mem_spin); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4079; }
    { const char * tb_v4080 = "TB_COLD static void tb_mem_die(int line, const char *what, int at) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4080; }
    { const char * tb_v4081 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v4081; }
    { const char * tb_v4082 = "    if (at > 0) snprintf(buf, sizeof buf, \"%s (блок из new_mem в строке %d)\", what, at);\n"; *(const char * *)tb_grow(v_lines) = tb_v4082; }
    { const char * tb_v4083 = "    else snprintf(buf, sizeof buf, \"%s\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v4083; }
    { const char * tb_v4084 = "    tb_mem_check = 0;   // программа падает: отчёт о неосвобождённом не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v4084; }
    { const char * tb_v4085 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4085; }
