    { const char * tb_v4145 = "        if (tb_mem_n == tb_mem_cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4145; }
    { const char * tb_v4146 = "            long long nc = tb_mem_cap ? tb_mem_cap * 2 : 256;\n"; *(const char * *)tb_grow(v_lines) = tb_v4146; }
    { const char * tb_v4147 = "            tb_memb *all = realloc(tb_mem_all, (size_t)nc * sizeof(tb_memb));\n"; *(const char * *)tb_grow(v_lines) = tb_v4147; }
    { const char * tb_v4148 = "            if (!all) tb_mem_die(line, \"не хватило памяти\", 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4148; }
    { const char * tb_v4149 = "            tb_mem_all = all; tb_mem_cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v4149; }
    { const char * tb_v4150 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4150; }
    { const char * tb_v4151 = "        tb_memb b = { (uintptr_t)p, (uint64_t)n, 1, line, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4151; }
    { const char * tb_v4152 = "        tb_mem_all[tb_mem_n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4152; }
    { const char * tb_v4153 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4153; }
    { const char * tb_v4154 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4154; }
