    { const char * tb_v4773 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4773; }
    { const char * tb_v4774 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4774; }
    { const char * tb_v4775 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4775; }
    { const char * tb_v4776 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4776; }
