    { const char * tb_v4793 = "       TB_K_PGDN = 11, TB_K_F1 = 128 };   // F1..F12 — 128..139\n"; *(const char * *)tb_grow(v_lines) = tb_v4793; }
    { const char * tb_v4794 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4794; }
    { const char * tb_v4795 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v4795; }
    { const char * tb_v4796 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v4796; }
    { const char * tb_v4797 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v4797; }
    { const char * tb_v4798 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v4798; }
    { const char * tb_v4799 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4799; }
    { const char * tb_v4800 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4800; }
    { const char * tb_v4801 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4801; }
    { const char * tb_v4802 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4802; }
    { const char * tb_v4803 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4803; }
    { const char * tb_v4804 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4804; }
    { const char * tb_v4805 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4805; }
    { const char * tb_v4806 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v4806; }
    { const char * tb_v4807 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4807; }
    { const char * tb_v4808 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4808; }
    { const char * tb_v4809 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4809; }
    { const char * tb_v4810 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v4810; }
    { const char * tb_v4811 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v4811; }
    { const char * tb_v4812 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4812; }
