    { const char * tb_v4814 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4814; }
    { const char * tb_v4815 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4815; }
    { const char * tb_v4816 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4816; }
    { const char * tb_v4817 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4817; }
    { const char * tb_v4818 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v4818; }
    { const char * tb_v4819 = "    memset(h->count, 0, sizeof h->count);\n"; *(const char * *)tb_grow(v_lines) = tb_v4819; }
    { const char * tb_v4820 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4820; }
    { const char * tb_v4821 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4821; }
    { const char * tb_v4822 = "    offs[1] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4822; }
    { const char * tb_v4823 = "    for (int l = 1; l < 15; l++) offs[l + 1] = offs[l] + h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v4823; }
    { const char * tb_v4824 = "    for (int i = 0; i < n; i++) if (len[i]) h->sym[offs[len[i]]++] = (short)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4824; }
    { const char * tb_v4825 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4825; }
    { const char * tb_v4826 = "TB_API int tb_hdec(tb_zs *z, const tb_huff *h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4826; }
    { const char * tb_v4827 = "    int code = 0, first = 0, index = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4827; }
