    { const char * tb_v4860 = "                for (int i = 256; i < 280; i++) lens[i] = 7;\n"; *(const char * *)tb_grow(v_lines) = tb_v4860; }
    { const char * tb_v4861 = "                for (int i = 280; i < 288; i++) lens[i] = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4861; }
    { const char * tb_v4862 = "                for (int i = 0; i < 30; i++) lens[288 + i] = 5;\n"; *(const char * *)tb_grow(v_lines) = tb_v4862; }
    { const char * tb_v4863 = "            } else {           // свои коды в начале блока\n"; *(const char * *)tb_grow(v_lines) = tb_v4863; }
    { const char * tb_v4864 = "                nl = (int)tb_zbits(z, 5) + 257; nd = (int)tb_zbits(z, 5) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4864; }
    { const char * tb_v4865 = "                int nc = (int)tb_zbits(z, 4) + 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v4865; }
    { const char * tb_v4866 = "                unsigned char cl[19] = { 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4866; }
    { const char * tb_v4867 = "                for (int i = 0; i < nc; i++) cl[order[i]] = (unsigned char)tb_zbits(z, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v4867; }
    { const char * tb_v4868 = "                tb_huff ch; tb_hbuild(&ch, cl, 19);\n"; *(const char * *)tb_grow(v_lines) = tb_v4868; }
    { const char * tb_v4869 = "                int i = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4869; }
    { const char * tb_v4870 = "                while (i < nl + nd && !z->err) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4870; }
    { const char * tb_v4871 = "                    int s = tb_hdec(z, &ch), rep = 0, val = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4871; }
    { const char * tb_v4872 = "                    if (s < 16) { lens[i++] = (unsigned char)s; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4872; }
    { const char * tb_v4873 = "                    if (s == 16) { if (!i) return 0; val = lens[i - 1]; rep = 3 + (int)tb_zbits(z, 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4873; }
    { const char * tb_v4874 = "                    else if (s == 17) rep = 3 + (int)tb_zbits(z, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v4874; }
    { const char * tb_v4875 = "                    else if (s == 18) rep = 11 + (int)tb_zbits(z, 7);\n"; *(const char * *)tb_grow(v_lines) = tb_v4875; }
    { const char * tb_v4876 = "                    else return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4876; }
