    { const char * tb_v5353 = "// GIF: первый кадр (LZW), палитра общая или своя, прозрачный цвет, через строку (interlace)\n"; *(const char * *)tb_grow(v_lines) = tb_v5353; }
    { const char * tb_v5354 = "TB_API uint32_t *tb_gif(const unsigned char *d, size_t n, int *pw, int *ph, const char **why) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5354; }
    { const char * tb_v5355 = "    *why = \"это не GIF\";\n"; *(const char * *)tb_grow(v_lines) = tb_v5355; }
    { const char * tb_v5356 = "    if (n < 13 || memcmp(d, \"GIF8\", 4) != 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5356; }
