    { const char * tb_v5363 = "    while (at < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5363; }
    { const char * tb_v5364 = "        int b = d[at++];\n"; *(const char * *)tb_grow(v_lines) = tb_v5364; }
