    { const char * tb_v5427 = "// любой формат: по первым байтам\n"; *(const char * *)tb_grow(v_lines) = tb_v5427; }
    { const char * tb_v5428 = "TB_API uint32_t *tb_image_decode(const unsigned char *d, size_t n, int *pw, int *ph, const char **why) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5428; }
