    { const char * tb_v5471 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5471; }
    { const char * tb_v5472 = "// image_from_mem(адрес, байт): картинка из памяти (файл прочитан со своего диска, пришёл по сети ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v5472; }
    { const char * tb_v5473 = "TB_API long long tb_image_from_mem(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5473; }
    { const char * tb_v5474 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v5474; }
    { const char * tb_v5475 = "    if (!a || n <= 0) { tb_err = \"пустая память\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5475; }
