    { const char * tb_v8081 = "    uint32_t a = 0x564D5868u, b = arg, c = cmd, d = 0x5658;\n"; *(const char * *)tb_grow(v_lines) = tb_v8081; }
    { const char * tb_v8082 = "    __asm__ volatile(\"inl %%dx, %%eax\" : \"+a\"(a), \"+b\"(b), \"+c\"(c), \"+d\"(d) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8082; }
    { const char * tb_v8083 = "    r[0] = a; r[1] = b; r[2] = c; r[3] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8083; }
    { const char * tb_v8084 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8084; }
