    { const char * tb_v8094 = "    tb_vmm_call(41, 0x53424152u, r);                     // точные координаты\n"; *(const char * *)tb_grow(v_lines) = tb_v8094; }
    { const char * tb_v8095 = "    tb_vmm = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8095; }
    { const char * tb_v8096 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8096; }
    { const char * tb_v8097 = "TB_API void tb_vmm_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8097; }
    { const char * tb_v8098 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v8098; }
    { const char * tb_v8099 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8099; }
