    { const char * tb_v8113 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8113; }
    { const char * tb_v8114 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v8114; }
    { const char * tb_v8115 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8115; }
