    { const char * tb_v8124 = "    if (tb_mpk[0] & 0xC0) dx = dy = 0;            // переполнение: пакет не верен\n"; *(const char * *)tb_grow(v_lines) = tb_v8124; }
    { const char * tb_v8125 = "    tb_mx += dx; tb_my -= dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8125; }
