    { const char * tb_v8127 = "    if (tb_my < 0) tb_my = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8127; }
    { const char * tb_v8128 = "    if (tb_mx >= tb_gw) tb_mx = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8128; }
