    { const char * tb_v8130 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8130; }
    { const char * tb_v8131 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8131; }
    { const char * tb_v8132 = "    tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v8132; }
