    { const char * tb_v9365 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9365; }
    { const char * tb_v9366 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v9366; }
