    { const char * tb_v9425 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9425; }
    { const char * tb_v9426 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v9426; }
    { const char * tb_v9427 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9427; }
    { const char * tb_v9428 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v9428; }
    { const char * tb_v9429 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9429; }
    { const char * tb_v9430 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v9430; }
    { const char * tb_v9431 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9431; }
    { const char * tb_v9432 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9432; }
    { const char * tb_v9433 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9433; }
    { const char * tb_v9434 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9434; }
    { const char * tb_v9435 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9435; }
    { const char * tb_v9436 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9436; }
    { const char * tb_v9437 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9437; }
    { const char * tb_v9438 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v9438; }
    { const char * tb_v9439 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9439; }
    { const char * tb_v9440 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v9440; }
    { const char * tb_v9441 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9441; }
    { const char * tb_v9442 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v9442; }
    { const char * tb_v9443 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9443; }
    { const char * tb_v9444 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9444; }
    { const char * tb_v9445 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v9445; }
    { const char * tb_v9446 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9446; }
    { const char * tb_v9447 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9447; }
    { const char * tb_v9448 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9448; }
    { const char * tb_v9449 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v9449; }
    { const char * tb_v9450 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9450; }
    { const char * tb_v9451 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9451; }
    { const char * tb_v9452 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9452; }
    { const char * tb_v9453 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9453; }
