    { const char * tb_v9455 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9455; }
    { const char * tb_v9456 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9456; }
    { const char * tb_v9457 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9457; }
    { const char * tb_v9458 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9458; }
    { const char * tb_v9459 = "        int top = row < r, bot = row >= h - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9459; }
    { const char * tb_v9460 = "        int lc = (top && (m & 1)) || (bot && (m & 4)), rc = (top && (m & 2)) || (bot && (m & 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v9460; }
    { const char * tb_v9461 = "        double cy = top ? y + r - 0.5 : y + h - r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v9461; }
    { const char * tb_v9462 = "        // середина строки — сплошняком\n"; *(const char * *)tb_grow(v_lines) = tb_v9462; }
