    { const char * tb_v9486 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v9486; }
    { const char * tb_v9487 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9487; }
