    { const char * tb_v9500 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v9500; }
    { const char * tb_v9501 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v9501; }
    { const char * tb_v9502 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9502; }
    { const char * tb_v9503 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9503; }
    { const char * tb_v9504 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9504; }
    { const char * tb_v9505 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9505; }
