    { const char * tb_v9534 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v9534; }
    { const char * tb_v9535 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9535; }
    { const char * tb_v9536 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9536; }
    { const char * tb_v9537 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9537; }
    { const char * tb_v9538 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9538; }
    { const char * tb_v9539 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v9539; }
    { const char * tb_v9540 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v9540; }
    { const char * tb_v9541 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9541; }
    { const char * tb_v9542 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9542; }
    { const char * tb_v9543 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9543; }
    { const char * tb_v9544 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9544; }
    { const char * tb_v9545 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9545; }
    { const char * tb_v9546 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9546; }
    { const char * tb_v9547 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9547; }
    { const char * tb_v9548 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9548; }
    { const char * tb_v9549 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9549; }
    { const char * tb_v9550 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9550; }
    { const char * tb_v9551 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9551; }
    { const char * tb_v9552 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9552; }
    { const char * tb_v9553 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9553; }
