    { const char * tb_v9617 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v9617; }
    { const char * tb_v9618 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v9618; }
    { const char * tb_v9619 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v9619; }
    { const char * tb_v9620 = "    v -= tb_fdiv(v, tx->h) * (long long)tx->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9620; }
