    { const char * tb_v9622 = "    return (*out >> 24) >= 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v9622; }
    { const char * tb_v9623 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9623; }
    { const char * tb_v9624 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v9624; }
    { const char * tb_v9625 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9625; }
    { const char * tb_v9626 = "    uint32_t r = (((t >> 16) & 255) * ((c >> 16) & 255) + 127) / 255, g = (((t >> 8) & 255) * ((c >> 8) & 255) + 127) / 255,\n"; *(const char * *)tb_grow(v_lines) = tb_v9626; }
