    { const char * tb_v9679 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v9679; }
    { const char * tb_v9680 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9680; }
    { const char * tb_v9681 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v9681; }
    { const char * tb_v9682 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9682; }
