    { const char * tb_v9746 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9746; }
    { const char * tb_v9747 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9747; }
    { const char * tb_v9748 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9748; }
    { const char * tb_v9749 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9749; }
    { const char * tb_v9750 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9750; }
    { const char * tb_v9751 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9751; }
    { const char * tb_v9752 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9752; }
    { const char * tb_v9753 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v9753; }
    { const char * tb_v9754 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9754; }
    { const char * tb_v9755 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9755; }
    { const char * tb_v9756 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9756; }
    { const char * tb_v9757 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9757; }
    { const char * tb_v9758 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v9758; }
    { const char * tb_v9759 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9759; }
    { const char * tb_v9760 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9760; }
    { const char * tb_v9761 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v9761; }
    { const char * tb_v9762 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9762; }
    { const char * tb_v9763 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v9763; }
    { const char * tb_v9764 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v9764; }
    { const char * tb_v9765 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9765; }
    { const char * tb_v9766 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v9766; }
    { const char * tb_v9767 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v9767; }
    { const char * tb_v9768 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v9768; }
    { const char * tb_v9769 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9769; }
    { const char * tb_v9770 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9770; }
    { const char * tb_v9771 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v9771; }
    { const char * tb_v9772 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v9772; }
    { const char * tb_v9773 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v9773; }
    { const char * tb_v9774 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v9774; }
    { const char * tb_v9775 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v9775; }
    { const char * tb_v9776 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v9776; }
    { const char * tb_v9777 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v9777; }
    { const char * tb_v9778 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9778; }
    { const char * tb_v9779 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v9779; }
    { const char * tb_v9780 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9780; }
    { const char * tb_v9781 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9781; }
    { const char * tb_v9782 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9782; }
    { const char * tb_v9783 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9783; }
    { const char * tb_v9784 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9784; }
    { const char * tb_v9785 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9785; }
    { const char * tb_v9786 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v9786; }
    { const char * tb_v9787 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v9787; }
    { const char * tb_v9788 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v9788; }
    { const char * tb_v9789 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v9789; }
    { const char * tb_v9790 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v9790; }
    { const char * tb_v9791 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v9791; }
    { const char * tb_v9792 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v9792; }
    { const char * tb_v9793 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v9793; }
    { const char * tb_v9794 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v9794; }
    { const char * tb_v9795 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v9795; }
    { const char * tb_v9796 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v9796; }
    { const char * tb_v9797 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v9797; }
    { const char * tb_v9798 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v9798; }
    { const char * tb_v9799 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v9799; }
    { const char * tb_v9800 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v9800; }
    { const char * tb_v9801 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v9801; }
    { const char * tb_v9802 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v9802; }
    { const char * tb_v9803 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v9803; }
    { const char * tb_v9804 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9804; }
    { const char * tb_v9805 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9805; }
    { const char * tb_v9806 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v9806; }
    { const char * tb_v9807 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v9807; }
    { const char * tb_v9808 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9808; }
    { const char * tb_v9809 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9809; }
    { const char * tb_v9810 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9810; }
    { const char * tb_v9811 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9811; }
    { const char * tb_v9812 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9812; }
