    { const char * tb_v9816 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9816; }
    { const char * tb_v9817 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9817; }
    { const char * tb_v9818 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9818; }
    { const char * tb_v9819 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9819; }
