    { const char * tb_v9822 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9822; }
    { const char * tb_v9823 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9823; }
    { const char * tb_v9824 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v9824; }
    { const char * tb_v9825 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9825; }
    { const char * tb_v9826 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v9826; }
    { const char * tb_v9827 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9827; }
    { const char * tb_v9828 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v9828; }
    { const char * tb_v9829 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v9829; }
