    { const char * tb_v9831 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9831; }
    { const char * tb_v9832 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9832; }
    { const char * tb_v9833 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9833; }
    { const char * tb_v9834 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v9834; }
