    { const char * tb_v9839 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9839; }
    { const char * tb_v9840 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v9840; }
    { const char * tb_v9841 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9841; }
    { const char * tb_v9842 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9842; }
    { const char * tb_v9843 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9843; }
    { const char * tb_v9844 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9844; }
    { const char * tb_v9845 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9845; }
    { const char * tb_v9846 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9846; }
    { const char * tb_v9847 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9847; }
    { const char * tb_v9848 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9848; }
    { const char * tb_v9849 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9849; }
    { const char * tb_v9850 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9850; }
    { const char * tb_v9851 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9851; }
    { const char * tb_v9852 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v9852; }
    { const char * tb_v9853 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v9853; }
    { const char * tb_v9854 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9854; }
    { const char * tb_v9855 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9855; }
    { const char * tb_v9856 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v9856; }
    { const char * tb_v9857 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9857; }
    { const char * tb_v9858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9858; }
    { const char * tb_v9859 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v9859; }
    { const char * tb_v9860 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9860; }
    { const char * tb_v9861 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9861; }
    { const char * tb_v9862 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v9862; }
    { const char * tb_v9863 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v9863; }
