    { const char * tb_v9882 = "// треугольник с картинкой: углы и (u, v) каждого — доли картинки (0…1, дальше повторяется); цвет белый\n"; *(const char * *)tb_grow(v_lines) = tb_v9882; }
    { const char * tb_v9883 = "TB_API void tb_mesh_add_uv(long long id, double x1, double y1, double z1, double u1, double v1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v9883; }
    { const char * tb_v9884 = "                           double u2, double v2, double x3, double y3, double z3, double u3, double v3) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9884; }
