    { const char * tb_v9894 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9894; }
    { const char * tb_v9895 = "// картинка для сетки: её треугольники из mesh_add_uv рисуются ею (остальные — своим цветом); -1 — без картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v9895; }
    { const char * tb_v9896 = "TB_API void tb_mesh_image(long long id, long long img) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9896; }
    { const char * tb_v9897 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9897; }
    { const char * tb_v9898 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v9898; }
    { const char * tb_v9899 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9899; }
    { const char * tb_v9900 = "    m->tex = img >= 0 && img < tb_nimg ? img : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9900; }
    { const char * tb_v9901 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9901; }
    { const char * tb_v9902 = "TB_API void tb_camera(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9902; }
    { const char * tb_v9903 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9903; }
    { const char * tb_v9904 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v9904; }
    { const char * tb_v9905 = "    for (int i = 0; i < 3; i++) f[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v9905; }
    { const char * tb_v9906 = "    double up[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9906; }
    { const char * tb_v9907 = "    if (fabs(f[1]) > 0.9999) { up[1] = 0; up[2] = 1; }   // смотрим прямо вверх или вниз\n"; *(const char * *)tb_grow(v_lines) = tb_v9907; }
    { const char * tb_v9908 = "    double r[3] = { up[1] * f[2] - up[2] * f[1], up[2] * f[0] - up[0] * f[2], up[0] * f[1] - up[1] * f[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v9908; }
    { const char * tb_v9909 = "    l = sqrt(r[0] * r[0] + r[1] * r[1] + r[2] * r[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9909; }
    { const char * tb_v9910 = "    for (int i = 0; i < 3; i++) r[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v9910; }
    { const char * tb_v9911 = "    double u[3] = { f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v9911; }
    { const char * tb_v9912 = "    tb_cam[0] = x; tb_cam[1] = y; tb_cam[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v9912; }
    { const char * tb_v9913 = "    for (int i = 0; i < 3; i++) { tb_cam[3 + i] = r[i]; tb_cam[6 + i] = u[i]; tb_camf[i] = f[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9913; }
    { const char * tb_v9914 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9914; }
    { const char * tb_v9915 = "// ---- свет: одно солнце (направление к нему) и фон; яркость грани — от того, как она повёрнута к солнцу ----\n"; *(const char * *)tb_grow(v_lines) = tb_v9915; }
    { const char * tb_v9916 = "// Всё в целых, одной формулой на процессоре и на видеокарте (tb3.vert, tb3.metal): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v9916; }
    { const char * tb_v9917 = "TB_API double tb_lt[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9917; }
    { const char * tb_v9918 = "TB_API int tb_lamb = -1;   // фон × 256; -1 — света нет, цвета как есть\n"; *(const char * *)tb_grow(v_lines) = tb_v9918; }
    { const char * tb_v9919 = "TB_API void tb_light(double dx, double dy, double dz, double amb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9919; }
    { const char * tb_v9920 = "    double l = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v9920; }
    { const char * tb_v9921 = "    if (!(l > 1e-12)) { tb_lamb = -1; return; }   // light(0, 0, 0, ...) — выключить\n"; *(const char * *)tb_grow(v_lines) = tb_v9921; }
    { const char * tb_v9922 = "    tb_lt[0] = dx / l; tb_lt[1] = dy / l; tb_lt[2] = dz / l;\n"; *(const char * *)tb_grow(v_lines) = tb_v9922; }
    { const char * tb_v9923 = "    if (!(amb > 0)) amb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9923; }
    { const char * tb_v9924 = "    if (amb > 1) amb = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9924; }
    { const char * tb_v9925 = "    tb_lamb = (int)tb_rnd(amb * 256);\n"; *(const char * *)tb_grow(v_lines) = tb_v9925; }
    { const char * tb_v9926 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9926; }
    { const char * tb_v9927 = "// нормали треугольников: (b - a) × (c - a), длина 2^14. У куба, где грани по кругу против часовой\n"; *(const char * *)tb_grow(v_lines) = tb_v9927; }
    { const char * tb_v9928 = "// стрелки снаружи, нормаль смотрит наружу\n"; *(const char * *)tb_grow(v_lines) = tb_v9928; }
    { const char * tb_v9929 = "static void tb_mesh_normals(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9929; }
    { const char * tb_v9930 = "    if (m->nrmok) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9930; }
    { const char * tb_v9931 = "    m->nrmok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9931; }
    { const char * tb_v9932 = "    if (m->nrmcap < m->n) { m->nrmcap = m->cap; m->nrm = (int32_t *)realloc(m->nrm, sizeof(int32_t) * 3 * (size_t)m->nrmcap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9932; }
    { const char * tb_v9933 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9933; }
    { const char * tb_v9934 = "        const double *a = m->v + 3 * m->t[3 * t], *b = m->v + 3 * m->t[3 * t + 1], *c = m->v + 3 * m->t[3 * t + 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9934; }
    { const char * tb_v9935 = "        double e1[3] = { b[0] - a[0], b[1] - a[1], b[2] - a[2] }, e2[3] = { c[0] - a[0], c[1] - a[1], c[2] - a[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v9935; }
    { const char * tb_v9936 = "        double n[3] = { e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v9936; }
    { const char * tb_v9937 = "        double l = sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9937; }
    { const char * tb_v9938 = "        for (int k = 0; k < 3; k++) m->nrm[3 * t + k] = l > 1e-300 ? (int32_t)tb_rnd(n[k] / l * 16384) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9938; }
    { const char * tb_v9939 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9939; }
    { const char * tb_v9940 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9940; }
    { const char * tb_v9941 = "// цвет грани под светом L (x, y, z, фон) — L уже в осях сетки; front — грань смотрит на нас\n"; *(const char * *)tb_grow(v_lines) = tb_v9941; }
    { const char * tb_v9942 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v9942; }
    { const char * tb_v9943 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9943; }
    { const char * tb_v9944 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9944; }
    { const char * tb_v9945 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9945; }
    { const char * tb_v9946 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9946; }
    { const char * tb_v9947 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9947; }
    { const char * tb_v9948 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v9948; }
    { const char * tb_v9949 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9949; }
    { const char * tb_v9950 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9950; }
    { const char * tb_v9951 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9951; }
    { const char * tb_v9952 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v9952; }
    { const char * tb_v9953 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9953; }
    { const char * tb_v9954 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v9954; }
    { const char * tb_v9955 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v9955; }
    { const char * tb_v9956 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v9956; }
    { const char * tb_v9957 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v9957; }
    { const char * tb_v9958 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v9958; }
    { const char * tb_v9959 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v9959; }
    { const char * tb_v9960 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v9960; }
    { const char * tb_v9961 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v9961; }
    { const char * tb_v9962 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v9962; }
    { const char * tb_v9963 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v9963; }
    { const char * tb_v9964 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v9964; }
    { const char * tb_v9965 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v9965; }
    { const char * tb_v9966 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v9966; }
    { const char * tb_v9967 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9967; }
    { const char * tb_v9968 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9968; }
    { const char * tb_v9969 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v9969; }
    { const char * tb_v9970 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v9970; }
    { const char * tb_v9971 = "TB_API tb_3v *tb_3vs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9971; }
    { const char * tb_v9972 = "TB_API long long tb_3vcap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9972; }
    { const char * tb_v9973 = "// старый путь (дроби): сетка задевает камеру или край, где целые не годятся — обрезка у камеры и рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v9973; }
    { const char * tb_v9974 = "TB_API long long *tb_3vst = 0, tb_3vgen = 0;   // какой угол уже посчитан в этом вызове\n"; *(const char * *)tb_grow(v_lines) = tb_v9974; }
    { const char * tb_v9975 = "// ---- картинка на сетке: плоскости u·W и v·W по трём углам ----\n"; *(const char * *)tb_grow(v_lines) = tb_v9975; }
    { const char * tb_v9976 = "// треугольник t сетки рисуется картинкой? (есть картинка, у треугольника есть (u, v), видеокарта умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v9976; }
    { const char * tb_v9977 = "TB_INL int tb_tex_on(const tb_mesh *m, long long t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9977; }
    { const char * tb_v9978 = "    return m->tex >= 0 && m->uv && !__builtin_isnan(m->uv[6 * t]) && (!tb_gpu_on || tb_gpu_tex);\n"; *(const char * *)tb_grow(v_lines) = tb_v9978; }
    { const char * tb_v9979 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9979; }
    { const char * tb_v9980 = "// (u, v) угла в 1/16 точки картинки, не дальше ±2^19 (чтобы плоскости влезли в 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v9980; }
    { const char * tb_v9981 = "TB_INL long long tb_tex_q(double u, int w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9981; }
    { const char * tb_v9982 = "    double q = u * w * 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9982; }
    { const char * tb_v9983 = "    if (!(q > -524288)) q = -524288;   // и NaN\n"; *(const char * *)tb_grow(v_lines) = tb_v9983; }
    { const char * tb_v9984 = "    if (q > 524288) q = 524288;\n"; *(const char * *)tb_grow(v_lines) = tb_v9984; }
    { const char * tb_v9985 = "    return tb_rnd(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v9985; }
    { const char * tb_v9986 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9986; }
    { const char * tb_v9987 = "// плоскость S по трём углам в целых: та же формула, что у плоскости глубины в tb_m3_tri\n"; *(const char * *)tb_grow(v_lines) = tb_v9987; }
    { const char * tb_v9988 = "static void tb_tex_plane_i(const long long *a, const long long *b, const long long *c, const long long *S, int64_t *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9988; }
    { const char * tb_v9989 = "    long long s0 = S[0], s1 = S[1], s2 = S[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9989; }
    { const char * tb_v9990 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9990; }
    { const char * tb_v9991 = "    if (area < 0) { const long long *k = b; b = c; c = k; long long ks = s1; s1 = s2; s2 = ks; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9991; }
