    { const char * tb_v10134 = "// деление с округлением вниз (b > 0); через числа без знака — одинаково на любой видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v10134; }
    { const char * tb_v10135 = "TB_INL long long tb_fdiv(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10135; }
