    { const char * tb_v10164 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v10164; }
    { const char * tb_v10165 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v10165; }
    { const char * tb_v10166 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v10166; }
    { const char * tb_v10167 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10167; }
    { const char * tb_v10168 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v10168; }
    { const char * tb_v10169 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v10169; }
    { const char * tb_v10170 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10170; }
    { const char * tb_v10171 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10171; }
    { const char * tb_v10172 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v10172; }
    { const char * tb_v10173 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10173; }
    { const char * tb_v10174 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10174; }
    { const char * tb_v10175 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v10175; }
    { const char * tb_v10176 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10176; }
    { const char * tb_v10177 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10177; }
    { const char * tb_v10178 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v10178; }
    { const char * tb_v10179 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v10179; }
    { const char * tb_v10180 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10180; }
    { const char * tb_v10181 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10181; }
    { const char * tb_v10182 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10182; }
    { const char * tb_v10183 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v10183; }
    { const char * tb_v10184 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10184; }
    { const char * tb_v10185 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10185; }
    { const char * tb_v10186 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v10186; }
    { const char * tb_v10187 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v10187; }
    { const char * tb_v10188 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10188; }
    { const char * tb_v10189 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10189; }
    { const char * tb_v10190 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v10190; }
    { const char * tb_v10191 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10191; }
