    { const char * tb_v10194 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники по две строки:\n"; *(const char * *)tb_grow(v_lines) = tb_v10194; }
    { const char * tb_v10195 = "// (номера углов, цвет) и (нормаль × 2^14, -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v10195; }
    { const char * tb_v10196 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10196; }
    { const char * tb_v10197 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10197; }
