    { const char * tb_v10208 = "                for (int k = 0; k < 3; k++) o[4 + k] = m->nrm[3 * t + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v10208; }
    { const char * tb_v10209 = "                o[7] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10209; }
