    { const char * tb_v10640 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v10640; }
    { const char * tb_v10641 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v10641; }
    { const char * tb_v10642 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v10642; }
    { const char * tb_v10643 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v10643; }
    { const char * tb_v10644 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v10644; }
    { const char * tb_v10645 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v10645; }
    { const char * tb_v10646 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v10646; }
    { const char * tb_v10647 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v10647; }
    { const char * tb_v10648 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v10648; }
    { const char * tb_v10649 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v10649; }
    { const char * tb_v10650 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v10650; }
    { const char * tb_v10651 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v10651; }
    { const char * tb_v10652 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v10652; }
    { const char * tb_v10653 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v10653; }
