    { const char * tb_v10981 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10981; }
    { const char * tb_v10982 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10982; }
    { const char * tb_v10983 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10983; }
    { const char * tb_v10984 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10984; }
    { const char * tb_v10985 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v10985; }
