    { const char * tb_v10988 = "        const unsigned char *c = b + p + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v10988; }
    { const char * tb_v10989 = "        if ((long)n > sz - p - 8) n = (uint32_t)(sz - p - 8);   // последний кусок обрезан — берём что есть\n"; *(const char * *)tb_grow(v_lines) = tb_v10989; }
    { const char * tb_v10990 = "        if (memcmp(b + p, \"fmt \", 4) == 0 && n >= 16) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10990; }
    { const char * tb_v10991 = "            tag = tb_le16(c); ch = tb_le16(c + 2); rate = tb_le32(c + 4); bits = tb_le16(c + 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v10991; }
    { const char * tb_v10992 = "            if (tag == 0xFFFE && n >= 26) tag = tb_le16(c + 24);   // «расширенный» WAV: вид внутри\n"; *(const char * *)tb_grow(v_lines) = tb_v10992; }
    { const char * tb_v10993 = "        } else if (memcmp(b + p, \"data\", 4) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10993; }
    { const char * tb_v10994 = "            data = c; dlen = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10994; }
