    { const char * tb_v10996 = "        p += 8 + (long)n + (n & 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10996; }
    { const char * tb_v10997 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10997; }
    { const char * tb_v10998 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v10998; }
    { const char * tb_v10999 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10999; }
    { const char * tb_v11000 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v11000; }
    { const char * tb_v11001 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v11001; }
    { const char * tb_v11002 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11002; }
