    { const char * tb_v11071 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11071; }
    { const char * tb_v11072 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v11072; }
    { const char * tb_v11073 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v11073; }
