    { const char * tb_v11075 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11075; }
    { const char * tb_v11076 = "        if (i < ramp) e = (double)i / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v11076; }
    { const char * tb_v11077 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v11077; }
    { const char * tb_v11078 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v11078; }
    { const char * tb_v11079 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11079; }
