    { const char * tb_v11462 = "# Запуск:  python3 elf_link.py вход.o -o выход.elf\n"; *(const char * *)tb_grow(v_lines) = tb_v11462; }
    { const char * tb_v11463 = "import struct\n"; *(const char * *)tb_grow(v_lines) = tb_v11463; }
