    { const char * tb_v11466 = "SHT_PROGBITS, SHT_SYMTAB, SHT_NOBITS, SHT_REL, SHT_RELA = 1, 2, 8, 9, 4\n"; *(const char * *)tb_grow(v_lines) = tb_v11466; }
    { const char * tb_v11467 = "SHF_WRITE, SHF_ALLOC, SHF_EXEC, SHF_TLS = 1, 2, 4, 0x400\n"; *(const char * *)tb_grow(v_lines) = tb_v11467; }
