    { const char * tb_v11472 = "def fail(msg):\n"; *(const char * *)tb_grow(v_lines) = tb_v11472; }
    { const char * tb_v11473 = "    sys.stderr.write(\"компоновка ядра: \" + msg + \"\\n\")\n"; *(const char * *)tb_grow(v_lines) = tb_v11473; }
    { const char * tb_v11474 = "    sys.exit(1)\n"; *(const char * *)tb_grow(v_lines) = tb_v11474; }
    { const char * tb_v11475 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11475; }
    { const char * tb_v11476 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11476; }
    { const char * tb_v11477 = "def align(x, a):\n"; *(const char * *)tb_grow(v_lines) = tb_v11477; }
    { const char * tb_v11478 = "    return x if a <= 1 else (x + a - 1) // a * a\n"; *(const char * *)tb_grow(v_lines) = tb_v11478; }
    { const char * tb_v11479 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11479; }
    { const char * tb_v11480 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11480; }
    { const char * tb_v11481 = "def main(argv):\n"; *(const char * *)tb_grow(v_lines) = tb_v11481; }
    { const char * tb_v11482 = "    ins, outs = [], []\n"; *(const char * *)tb_grow(v_lines) = tb_v11482; }
    { const char * tb_v11483 = "    i = 1\n"; *(const char * *)tb_grow(v_lines) = tb_v11483; }
