    { const char * tb_v11510 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11510; }
    { const char * tb_v11511 = "    # группы по порядку раскладки\n"; *(const char * *)tb_grow(v_lines) = tb_v11511; }
    { const char * tb_v11512 = "    def group(s):\n"; *(const char * *)tb_grow(v_lines) = tb_v11512; }
    { const char * tb_v11513 = "        n = s[\"name\"]\n"; *(const char * *)tb_grow(v_lines) = tb_v11513; }
