    { const char * tb_v11525 = "            return 5\n"; *(const char * *)tb_grow(v_lines) = tb_v11525; }
    { const char * tb_v11526 = "        return 3\n"; *(const char * *)tb_grow(v_lines) = tb_v11526; }
    { const char * tb_v11527 = "    alloc = [k for k, s in enumerate(secs) if s[\"flags\"] & SHF_ALLOC and s[\"type\"] in (SHT_PROGBITS, SHT_NOBITS) and s[\"size\"] > 0]\n"; *(const char * *)tb_grow(v_lines) = tb_v11527; }
    { const char * tb_v11528 = "    # переменные потока: сначала с начальными значениями (.tdata), потом нулевые (.tbss)\n"; *(const char * *)tb_grow(v_lines) = tb_v11528; }
