    { const char * tb_v11531 = "            fail(\"переменная потока выровнена больше чем на 16 байт\")\n"; *(const char * *)tb_grow(v_lines) = tb_v11531; }
    { const char * tb_v11532 = "    order = sorted(alloc, key=lambda k: (group(secs[k]), secs[k][\"type\"] == SHT_NOBITS, k))\n"; *(const char * *)tb_grow(v_lines) = tb_v11532; }
