    { const char * tb_v11534 = "    # символы, которым нужна ячейка в GOT\n"; *(const char * *)tb_grow(v_lines) = tb_v11534; }
    { const char * tb_v11535 = "    got_syms = []\n"; *(const char * *)tb_grow(v_lines) = tb_v11535; }
