    { const char * tb_v11538 = "            for k in range(s[\"size\"] // 24):\n"; *(const char * *)tb_grow(v_lines) = tb_v11538; }
    { const char * tb_v11539 = "                r_info, = struct.unpack_from(\"<Q\", data, s[\"off\"] + k * 24 + 8)\n"; *(const char * *)tb_grow(v_lines) = tb_v11539; }
    { const char * tb_v11540 = "                if r_info & 0xFFFFFFFF in (9, 41, 42) and r_info >> 32 not in got_syms:\n"; *(const char * *)tb_grow(v_lines) = tb_v11540; }
    { const char * tb_v11541 = "                    got_syms.append(r_info >> 32)\n"; *(const char * *)tb_grow(v_lines) = tb_v11541; }
