    { const char * tb_v11557 = "    ksym_size = 16 * (len(exports) + len(ext_names)) + sum(len(n) + 1 for n, _ in exports) + sum(len(n) + 1 for n in ext_names)\n"; *(const char * *)tb_grow(v_lines) = tb_v11557; }
